import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.DmGDJU50.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),o={name:"explanation/architecture.md"};function n(r,e,d,c,h,l){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>One long-lived <strong>age identity</strong> per person per machine — the master key every age-encrypted store on the box decrypts with. tardigrada owns that key&#39;s <em>lifecycle</em>: bootstrap, inspect, move. It never touches ciphertext, vaults, refs, or envs — those belong to the consumers (cuora, tamias sealed packs, rage).</p><p>Named for the tardigrade: the animal survives anything by entering cryptobiosis — a dormant state it persists through until conditions return. The identity sleeps in a keyfile (<code>0600</code>) and wakes whenever a store needs it; it persists across tools, machines, and years.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tardigrada (CLI)</span></span>
<span class="line"><span>   │  clap parse → dispatch → i32        (crates/tardigrada, lib + thin bin)</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>FileIdentity  ── the keyfile impl (cuora-identity-file, crates.io)</span></span>
<span class="line"><span>   │  load: first non-comment line → x25519::Identity</span></span>
<span class="line"><span>   │  store: &quot;#&quot; header + AGE-SECRET-KEY-…, mode 0600, fsync</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>identity.txt  ── $TARDIGRADA_IDENTITY_FILE → $XDG_CONFIG_HOME/</span></span>
<span class="line"><span>                tardigrada/identity.txt → ~/.config/…</span></span></code></pre></div><p>Single crate, no driver: the command ships as a tamias <code>type: files</code> pack with a <code>payload:</code> bin (<code>libraries/tardigrada</code>) — a real binary staged by <code>scripts/pack.sh</code>, deployed onto PATH by <code>tamias install</code>. Same shape as <code>tarsi</code>&#39;s pack; no <code>bins[]</code> shim, no <code>tamias-driver-*</code> crate.</p><h2 id="ports-inherited-not-reinvented" tabindex="-1">Ports (inherited, not reinvented) <a class="header-anchor" href="#ports-inherited-not-reinvented" aria-label="Permalink to &quot;Ports (inherited, not reinvented)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Source</th></tr></thead><tbody><tr><td><code>IdentitySource</code> port + <code>ensure()</code></td><td><code>cuora-identity</code> (crates.io <code>0.1</code>)</td></tr><tr><td><code>FileIdentity</code> keyfile impl</td><td><code>cuora-identity-file</code> (crates.io <code>0.1</code>)</td></tr><tr><td><code>x25519::Identity</code></td><td><code>age</code> (default-features off)</td></tr></tbody></table><p><code>tardigrada</code> calls <code>FileIdentity::new(&lt;resolved path&gt;)</code> — the impl is path-agnostic, so tardigrada&#39;s <code>~/.config/tardigrada/</code> location and cuora&#39;s <code>~/.config/cuora/</code> location are the same code.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>Delivery → memory → process → interface: tardigrada is <strong>process</strong> infrastructure — a lifecycle tool other tools&#39; identities flow through. cuora (secrets broker) consumes the identity for vault decryption; tamias (distribution) ships the binary; myco (work memory) tracks the ledger; tarsi (release plane) cuts the tags.</p><h2 id="neighbors" tabindex="-1">Neighbors <a class="header-anchor" href="#neighbors" aria-label="Permalink to &quot;Neighbors&quot;">​</a></h2><p>See <a href="./boundaries.html">Boundaries</a> for the owns / doesn&#39;t-own split and the per-neighbor relationship table; <a href="./decisions.html">Decisions</a> for the why behind each of those lines.</p>`,14)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
